style.css:
@-moz-document domain("roblox.com") {
/* ? Root variables for easy editing */
    :root {
        --main-bg: #000014;
        --second-bg: #00001a;
        --input-bg: #00001f;
        --main-text: #Db0000;
        --link-text: #ff2a2a;
    }

    /* ? Background & Containers */
    html, body, 
    .content, 
    .container-main, 
    .rbx-body, 
    .section-content,
    #container-main,
    .gui-container {
        background-color: var(--main-bg) !important;
    }

    /* ? Text Elements - Targeted to avoid breaking icons */
    body, p, span, li, h1, h2, h3, h4, h5, h6, 
    .text-label, .text-main, .text-title, .text-name {
        color: var(--main-text) !important;
    }

    /* ? Buttons - Added a hover state for usability */
    .btn-primary, .btn-secondary, .btn-control, button {
        background-color: transparent !important;
        color: var(--main-text) !important;
        border: 1px solid var(--main-text) !important; /* Added thin border so you can see them */
        box-shadow: none !important;
    }
    
    .btn-primary:hover, button:hover {
        background-color: rgba(219, 0, 0, 0.1) !important;
    }

    /* ? Navigation & Header */
    .rbx-header, 
    #header,
    .rbx-navbar, 
    .left-col-navigation {
        background-color: var(--main-bg) !important;
        border: none !important;
    }

    /* ? Inputs & Search */
    input, .form-control, .search-input {
        background-color: var(--input-bg) !important;
        color: var(--main-text) !important;
        border: 1px solid #333 !important;
    }

    /* ? Cards / Panels */
    .card, .section, .container-header, .rbx-panel, .item-card-container, .menu-sidebar-container {
        background-color: var(--second-bg) !important;
        border: none !important;
    }

    /* ? Links */
    a, .text-link {
        color: var(--link-text) !important;
    }

    /* ? Targeted border removal (Better than using *) */
    .rbx-header, .section-content, .container-header, .footer {
        border: none !important;
        outline: none !important;
        box-shadow: none !important;
    }

    /* ?️ Icons (Recoloring standard icons to Red) */
    .icon-logo, .icon-default-navigation, .rbx-icon-nav-search,
    [class^="icon-"], [class*=" icon-"] {
        filter: brightness(0) saturate(100%) invert(13%) sepia(100%) saturate(6000%) hue-rotate(0deg) !important;
    }

    /* ? PROTECTION: Keep Thumbnails & Avatars Normal */
    .game-card-thumb img, 
    .avatar-card-fullbody img, 
    .avatar-headshot img, 
    .thumbnail-2d-container img {
        filter: none !important;
    }

    /* ? Scrollbar Customization */
    ::-webkit-scrollbar {
        width: 8px;
    }
    ::-webkit-scrollbar-track {
        background: var(--main-bg);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--main-text);
        border-radius: 10px;
    }
}
